#!/usr/bin/env node
import { readFile } from 'node:fs/promises';
import { dirname, isAbsolute, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { REPO_TO_STAX_CONVERTER_VERSION, } from './analyze-cli.js';
import { convertRepoToStax } from './lib/converter.js';
export const REPO_TO_STAX_PREPARE_PROTOCOL = 'repo-to-stax.prepare.v1';
const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const bundledTemplateRoot = resolve(packageRoot, 'template', 'takuai-template');
const bundledTemplateProvenancePath = resolve(packageRoot, 'template-provenance.json');
export async function prepareCandidateForPublisher(args) {
    if (!isAbsolute(args.outputRoot)) {
        throw new Error('Candidate output root must be an absolute path.');
    }
    if (!isAbsolute(args.workRoot)) {
        throw new Error('Candidate source work root must be an absolute path.');
    }
    if (!/^sha256:[a-f0-9]{64}$/.test(args.expectedSourceDigest)) {
        throw new Error('Expected source digest is invalid.');
    }
    const provenance = await readBundledTemplateProvenance();
    const result = await convertRepoToStax({
        input: args.input,
        outputRoot: args.outputRoot,
        sourceWorkRoot: args.workRoot,
        templateRoot: bundledTemplateRoot,
        templateSource: provenance,
        ...(args.sourceRef ? { sourceRef: args.sourceRef } : {}),
        ...(args.name ? { name: args.name } : {}),
        expectedSourceDigest: args.expectedSourceDigest,
    });
    return {
        protocol: REPO_TO_STAX_PREPARE_PROTOCOL,
        converterVersion: REPO_TO_STAX_CONVERTER_VERSION,
        sourceDigest: result.sourceDigest,
        template: {
            version: provenance.version,
            ref: provenance.resolvedRef,
            commit: provenance.commit,
        },
        workspaceRoot: result.workspaceRoot,
        analysis: result.analysis,
        route: result.route,
        workspaceValidation: result.workspaceValidation,
    };
}
async function readBundledTemplateProvenance() {
    const parsed = JSON.parse(await readFile(bundledTemplateProvenancePath, 'utf8'));
    if (parsed.schemaVersion !== 'taku.bundled-subapp-template.v1' ||
        parsed.sourceKind !== 'github' ||
        typeof parsed.sourceUrl !== 'string' ||
        typeof parsed.requestedRef !== 'string' ||
        typeof parsed.resolvedRef !== 'string' ||
        typeof parsed.commit !== 'string' ||
        parsed.dirty !== false ||
        typeof parsed.version !== 'string') {
        throw new Error('Bundled Taku SubApp template provenance is invalid.');
    }
    return parsed;
}
function parseArguments(argv) {
    if (argv[0] !== 'prepare' || !argv[1]) {
        throw new Error('Usage: prepare-cli prepare <repo-or-path> --output-root <dir> --work-root <dir> --expected-source-digest <sha256> [--source-ref <ref>] [--name <name>]');
    }
    const input = argv[1];
    const values = new Map();
    for (let index = 2; index < argv.length; index += 2) {
        const flag = argv[index];
        const value = argv[index + 1];
        if (!flag?.startsWith('--') || !value) {
            throw new Error(`Invalid prepare argument: ${flag || '<missing>'}`);
        }
        if (!['--output-root', '--work-root', '--expected-source-digest', '--source-ref', '--name'].includes(flag)) {
            throw new Error(`Unsupported prepare argument: ${flag}`);
        }
        if (values.has(flag))
            throw new Error(`Duplicate prepare argument: ${flag}`);
        values.set(flag, value);
    }
    const outputRoot = values.get('--output-root');
    const workRoot = values.get('--work-root');
    const expectedSourceDigest = values.get('--expected-source-digest');
    if (!outputRoot)
        throw new Error('--output-root is required');
    if (!workRoot)
        throw new Error('--work-root is required');
    if (!expectedSourceDigest)
        throw new Error('--expected-source-digest is required');
    const sourceRef = values.get('--source-ref');
    const name = values.get('--name');
    return {
        input,
        outputRoot,
        workRoot,
        expectedSourceDigest,
        ...(sourceRef ? { sourceRef } : {}),
        ...(name ? { name } : {}),
    };
}
async function main() {
    const result = await prepareCandidateForPublisher(parseArguments(process.argv.slice(2)));
    process.stdout.write(`${JSON.stringify(result)}\n`);
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
    main().catch((error) => {
        process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
        process.exitCode = 1;
    });
}
